/**
 * Answer mode is FROZEN (P review of the Grapher, docs/roles/audits/P-grapher-review.md item 1).
 *
 * The Grapher's grammar (`grammar: 'grapher'` in physics/expr.ts: "2 3" and "sin 2x" become errors) must not reach
 * any other caller. This table was generated from the parser BEFORE that grammar landed and committed first; every
 * row is asserted IDENTICAL after it. A row records, for one input, every answer-mode caller whole:
 *   - ui/parseNumber (every learner answer and challenge; whitespace deleted, the pre-W1 rule);
 *   - `parse` in real mode with the answer limits (the Operator Lab's τ field), with its value;
 *   - complex mode with the answer limits (the Operator Lab's generator) and the cell limits (typed matrix cells), and
 *     parseMatrix2 itself;
 *   - the grapher's function set WITHOUT the grapher grammar (`fns: 'grapher'` alone reads exactly as before).
 * The parse results are kept whole (the AST, or the caret and the reason), so a changed tree fails too, not only a
 * changed value. Inputs: spaces between numbers, functions with bare arguments, units, the Unicode operators.
 */
import { describe, expect, it } from 'vitest'
import { parseNumber } from '../ui/parseNumber'
import { LIMITS, evalComplex, evalReal, parse, parseMatrix2, type Parsed } from './expr'

const enc = (v: unknown): string => JSON.stringify(v, (_k, x: unknown) => (typeof x === 'number' && !Number.isFinite(x) ? `#${String(x)}` : x))
const ENV = new Map([['x', 0.7], ['t', 1.3]])
const realValue = (r: Parsed) => (r.ok ? evalReal(r.ast, ENV) : null)
const complexValue = (r: Parsed) => (r.ok ? evalComplex(r.ast) : null)

function row(src: string): string {
  const real = parse(src, { mode: 'real', limits: LIMITS.answer })
  const complex = parse(src, { mode: 'complex', limits: LIMITS.answer })
  const cell = parse(src, { mode: 'complex', limits: LIMITS.cell })
  const fns = parse(src, { mode: 'real', limits: LIMITS.grapher, fns: 'grapher', vars: ['x', 't'] })
  const m = parseMatrix2([[src, '0'], ['0', '0']])
  return enc({
    parseNumber: parseNumber(src),
    real,
    realValue: realValue(real),
    complex,
    complexValue: complexValue(complex),
    cell: enc(cell) === enc(complex) ? '=complex' : cell,
    matrix: m.ok ? m.M[0][0] : m,
    grapherFnsOnly: fns,
    grapherFnsOnlyValue: realValue(fns),
  })
}

