describe('answer mode is unchanged by the grapher grammar (review #1)', () => {
  it('the table covers the inputs the review names ("2 3", "1 / 2", "sin 2x", "cos pi t", "x^2 3")', () => {
    const inputs = TABLE.map(([s]) => s)
    for (const s of ['2 3', '1 / 2', 'sin 2x', 'cos pi t', 'x^2 3']) expect(inputs).toContain(s)
    expect(new Set(inputs).size).toBe(inputs.length)
    expect(inputs).toEqual([...INPUTS])
  })
  it.each(TABLE)('%j reads exactly as before', (src, want) => {
    expect(row(src)).toBe(want)
  })
})
